import{_ as n,o as t,c as r,a2 as i}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse('{"title":"Gesetz zum Umweltschutz","description":"","frontmatter":{},"headers":[],"relativePath":"de/46-环境保护法.md","filePath":"de/46-环境保护法.md"}'),s={name:"de/46-环境保护法.md"};function u(d,e,a,l,g,h){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="gesetz-zum-umweltschutz" tabindex="-1">Gesetz zum Umweltschutz <a class="header-anchor" href="#gesetz-zum-umweltschutz" aria-label="Permalink to &quot;Gesetz zum Umweltschutz&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Projekt</th><th>Inhalt</th></tr></thead><tbody><tr><td>Dokumentennummer</td><td>46</td></tr><tr><td>Modul</td><td>Rechtssystem und Governance-Rahmen</td></tr><tr><td>Kernschlüsselwörter</td><td>Umweltschutz, Ursprung des Universums, ökologische Symbiose, nachhaltige Entwicklung, Verhütung und Bekämpfung der Umweltverschmutzung</td></tr></tbody></table><h2 id="i-legislatives-ziel-und-grundprinzipien" tabindex="-1">I. Legislatives Ziel und Grundprinzipien <a class="header-anchor" href="#i-legislatives-ziel-und-grundprinzipien" aria-label="Permalink to &quot;I. Legislatives Ziel und Grundprinzipien&quot;">​</a></h2><p>Das 《Gesetz zum Umweltschutz》 ist eines der fünf ergänzenden Gesetze der Anker-Symbiose-Zivilisation. Es zielt darauf ab, die ökologische Umwelt und den Ursprung des Universums von Hengyuanzhou zu schützen, das Konzept der Umweltregierung &quot;symbiotische Evolution, nachhaltige Entwicklung&quot; zu etablieren, die Zerstörung des universellen Ökosystems durch räuberische Ausbeutung zu verhindern und die Grundlage des Überlebens für den gemeinsamen Fortschritt aller Rassen zu schützen.</p><p>Dieses Gesetz legt folgende Grundprinzipien fest:</p><table tabindex="0"><thead><tr><th>Prinzip</th><th>Inhalt</th></tr></thead><tbody><tr><td>Prinzip des Ursprungsschutzes</td><td>Der Ursprung des Universums ist die Grundlage allen Lebens und aller Evolution, muss vorrangig geschützt werden, und zerstörerischer Abbau ist verboten</td></tr><tr><td>Prinzip der ökologischen Symbiose</td><td>Mensch und Natur, jede Rasse und das Ökosystem stehen in einer symbiotischen Beziehung, und die Zerstörung der Ökologie ist die Zerstörung der eigenen Überlebensgrundlage</td></tr><tr><td>Prinzip der Nachhaltigkeit</td><td>Alle Ausbeutungsaktivitäten müssen die Interessen der gegenwärtigen und künftigen Generationen berücksichtigen, und die Ausbeutung bis zur Erschöpfung wird abgelehnt</td></tr><tr><td>Prinzip der Vorbeugung als Hauptsache</td><td>Der Umweltschutz legt den Schwerpunkt auf die Vorbeugung, baut ein System der Umweltverträglichkeitsprüfung auf und verhindert das Auftreten von Umweltverschmutzung</td></tr><tr><td>Prinzip der Verantwortung des Verursachers</td><td>Der Verursacher von Umweltverschmutzung und ökologischer Zerstörung muss die Verantwortung für Sanierung und Entschädigung übernehmen</td></tr><tr><td>Prinzip der öffentlichen Beteiligung</td><td>Förderung der öffentlichen Beteiligung am Umweltschutz, Gewährleistung des Rechts der Öffentlichkeit auf Umweltinformation und Beteiligung</td></tr><tr><td>Prinzip der inter-ebenen Zusammenarbeit</td><td>Der Umweltschutz wird durch inter-ebene Zusammenarbeit vorangetrieben, und es wird ein Mechanismus für die Zusammenarbeit bei der Umweltregierung zwischen Ebenen aufgebaut</td></tr></tbody></table><h2 id="ii-umfang-des-umweltschutzes" tabindex="-1">II. Umfang des Umweltschutzes <a class="header-anchor" href="#ii-umfang-des-umweltschutzes" aria-label="Permalink to &quot;II. Umfang des Umweltschutzes&quot;">​</a></h2><p>Der durch dieses Gesetz geschützte Umweltumfang umfasst alle Ökosysteme und UmweltElemente innerhalb von Hengyuanzhou:</p><ol><li><strong>Atmosphärische Umwelt</strong>: Umfasst die Atmosphäre jedes Planeten, die Energiekonzentration und das Zusammensetzungsgleichgewicht der Energieschichten.</li><li><strong>Wasserumwelt</strong>: Umfasst die Wasserqualität und -menge von Oberflächenwasser, Grundwasser, Ozeanen und Energiegewässern zwischen Ebenen.</li><li><strong>Bodenumwelt</strong>: Umfasst die Bodenqualität und Fruchtbarkeit von Landböden und Erzadern von Kultivierungsressourcen.</li><li><strong>Biodiversität</strong>: Umfasst den Artenschutz und den Schutz der Lebensräume aller Tiere und Pflanzen, Mikroorganismen und seltsamen Lebens.</li><li><strong>Energieumwelt</strong>: Umfasst die Konzentration und das Verteilungsgleichgewicht von Himmels-Erde-Geist-Energie, Ursprungsenergie und Gesetzesfragmenten.</li><li><strong>Raumumwelt</strong>: Umfasst die räumliche Stabilität der Ebenen, Raumrisse und die Umweltsicherheit von gefalteten Räumen.</li><li><strong>Bewusstseinsdomänen-Umwelt</strong>: Umfasst die Informationssauberkeit des kollektiven Bewusstseinsraums und die Verhütung von geistiger Verschmutzung.</li></ol><h2 id="iii-wichtige-systeme" tabindex="-1">III. Wichtige Systeme <a class="header-anchor" href="#iii-wichtige-systeme" aria-label="Permalink to &quot;III. Wichtige Systeme&quot;">​</a></h2><h3 id="_1-system-der-umweltvertraglichkeitsprufung" tabindex="-1">(1) System der Umweltverträglichkeitsprüfung <a class="header-anchor" href="#_1-system-der-umweltvertraglichkeitsprufung" aria-label="Permalink to &quot;(1) System der Umweltverträglichkeitsprüfung&quot;">​</a></h3><p>Alle Entwicklungs- und Bauprojekte, die erhebliche Auswirkungen auf die Umwelt haben können, müssen vor Baubeginn eine Umweltverträglichkeitsprüfung durchlaufen. Der Prüfungsinhalt umfasst: die Auswirkungen des Projekts auf UmweltElemente wie Atmosphäre, Wasser, Boden, Organismen, Energie, Raum usw., Präventions- und Minderungsmaßnahmen, Umweltrisikobewertung usw. Projekte, die die Umweltverträglichkeitsprüfung nicht bestehen, dürfen nicht mit dem Bau beginnen.</p><h3 id="_2-system-der-emissionsgenehmigung-und-gesamtmengensteuerung" tabindex="-1">(2) System der Emissionsgenehmigung und Gesamtmengensteuerung <a class="header-anchor" href="#_2-system-der-emissionsgenehmigung-und-gesamtmengensteuerung" aria-label="Permalink to &quot;(2) System der Emissionsgenehmigung und Gesamtmengensteuerung&quot;">​</a></h3><p>Der Staat führt für die Emission von Schadstoffen eine Genehmigungsverwaltung und eine Gesamtmengensteuerung durch. Emissionseinheiten müssen eine Emissionsgenehmigung einholen und Schadstoffe gemäß den in der Genehmigung festgelegten Arten, Konzentrationen und Gesamtmengen emittieren. Der Staat legt die Gesamtemissionsmenge der Schadstoffe jeder Region und jeder Ebene entsprechend der Umweltbelastbarkeit fest und setzt sie schrittweise um.</p><h3 id="_3-system-der-okologischen-schutzgrenze" tabindex="-1">(3) System der ökologischen Schutzgrenze <a class="header-anchor" href="#_3-system-der-okologischen-schutzgrenze" aria-label="Permalink to &quot;(3) System der ökologischen Schutzgrenze&quot;">​</a></h3><p>Der Staat zieht in Gebieten mit besonderem ökologischem Wert ökologische Schutzgrenzen, einschließlich:</p><table tabindex="0"><thead><tr><th>Art der Schutzgrenze</th><th>Schutzinhalt</th></tr></thead><tbody><tr><td>Ursprungsschutzgebiet</td><td>Kernproduktionsgebiet der Ursprungsenergie des Universums, alle Ausbeutungsaktivitäten sind verboten</td></tr><tr><td>Artenlebensraum</td><td>Kernlebensraum seltener und gefährdeter Arten, Zerstörung und Störung sind verboten</td></tr><tr><td>Ökologisches Barrierengebiet</td><td>Schlüsselökosystem zur Aufrechterhaltung des regionalen ökologischen Gleichgewichts, Ausbeutung ist eingeschränkt</td></tr><tr><td>Kultivierungsheiligtum</td><td>Energiereiches Gebiet mit besonderem Kultivierungswert, führt schützende Nutzung durch</td></tr><tr><td>Ebenengrenzzone</td><td>Ökologische Übergangszone zwischen Ebenen, räumlich zerstörerische Ausbeutung ist verboten</td></tr></tbody></table><h3 id="_4-system-der-umweltuberwachung-und-warnung" tabindex="-1">(4) System der Umweltüberwachung und -warnung <a class="header-anchor" href="#_4-system-der-umweltuberwachung-und-warnung" aria-label="Permalink to &quot;(4) System der Umweltüberwachung und -warnung&quot;">​</a></h3><p>Der Staat baut ein Umweltüberwachungsnetz auf, das das gesamte Universum abdeckt, und überwacht die Veränderungen jedes UmweltElements in Echtzeit. Für mögliche schwere Umweltverschmutzungs- und ökologische Zerstörungsereignisse wird ein Warnmechanismus aufgebaut, Warninformationen rechtzeitig veröffentlicht und die Notfallreaktion gestartet.</p><h3 id="_5-system-der-okologischen-kompensation" tabindex="-1">(5) System der ökologischen Kompensation <a class="header-anchor" href="#_5-system-der-okologischen-kompensation" aria-label="Permalink to &quot;(5) System der ökologischen Kompensation&quot;">​</a></h3><p>Regionen und Gruppen, deren Ausbeutung aufgrund des Umweltschutzes eingeschränkt ist, haben das Recht auf ökologische Kompensation. Die Mittel für die ökologische Kompensation werden aus der öffentlichen Rücklage und den Erträgen aus der Ressourcenausbeutung bestritten und für die wirtschaftliche Entwicklung der Kompensationsregion sowie die Verbesserung des Lebens der Bewohner verwendet.</p><h2 id="iv-umweltregulierung-von-kultivierungsaktivitaten" tabindex="-1">IV. Umweltregulierung von Kultivierungsaktivitäten <a class="header-anchor" href="#iv-umweltregulierung-von-kultivierungsaktivitaten" aria-label="Permalink to &quot;IV. Umweltregulierung von Kultivierungsaktivitäten&quot;">​</a></h2><p>Die Auswirkungen von Kultivierungsaktivitäten auf die Umwelt sind ein besonderes Gebiet des Umweltschutzes von Hengyuanzhou, und dieses Gesetz sieht speziell Regulierungsbestimmungen vor:</p><ol><li><strong>Regulierung des Energieabbaus</strong>: Der Abbau von Kultivierungsressourcen muss dem Nachhaltigkeitsprinzip entsprechen, und zerstörerischer Abbau, der zur Energieerschöpfung führt, ist verboten. Die Abbaumenge darf die natürliche Erholungsgeschwindigkeit der regionalen Energie nicht überschreiten.</li><li><strong>Entsorgung von Kultivierungsabfällen</strong>: Energiertückstände, entsorgte Kultivierungspillen, beschädigte Instrumente usw., die während des Kultivierungsprozesses anfallen, müssen gemäß den Bestimmungen entsorgt werden, und willkürliches Entsorgen, das Energieverschmutzung verursacht, ist verboten.</li><li><strong>Umweltbewertung für fortgeschrittene Kultivierung</strong>: Der Durchbruch und die Rückzugsphase von fortgeschrittenen Kultivierern können erhebliche Auswirkungen auf die Umgebung haben, und müssen vorher eine Umweltbewertung durchlaufen und Schutzmaßnahmen ergreifen.</li><li><strong>Genehmigung für die Ebenenentwicklung</strong>: Die Entwicklung neuer Ebenen muss eine Umweltbewertung und ökologische Untersuchung durchlaufen und kann erst nach Erstellung eines ökologischen Schutzplans durchgeführt werden.</li><li><strong>Schutz der Lebensräume seltsamen Lebens</strong>: Die Lebensräume seltsamen Lebens werden in die ökologische Schutzgrenze einbezogen, und Erforschung und Ausbeutung ohne Genehmigung sind verboten.</li></ol><h2 id="v-rechtliche-verantwortung" tabindex="-1">V. Rechtliche Verantwortung <a class="header-anchor" href="#v-rechtliche-verantwortung" aria-label="Permalink to &quot;V. Rechtliche Verantwortung&quot;">​</a></h2><p>Handlungen, die gegen die Bestimmungen dieses Gesetzes verstoßen, tragen je nach Schwere des Verstoßes folgende Verantwortung:</p><ul><li>Beginn des Baus ohne bestandene Umweltverträglichkeitsprüfung, Anordnung zum Stopp des Baus, Wiederherstellung des ursprünglichen Zustands und Geldbuße.</li><li>Überschreitung der Standards bei der Emission von Schadstoffen, Anordnung zur fristgerechten Sanierung und Geldbuße, in schweren Fällen Anordnung zur Schließung des Betriebs.</li><li>Zerstörung der ökologischen Schutzgrenze, Anordnung zur Wiederherstellung des ursprünglichen Zustands und Geldbuße, in schweren Fällen strafrechtliche Verfolgung.</li><li>Zerstörerischer Abbau von Kultivierungsressourcen, Einziehung der rechtswidrigen Erträge und Geldbuße, Entzug der Abbaugenehmigung.</li><li>Verursachung schwerer Umweltverschmutzungsunfälle, Übernahme der Entschädigungsverantwortung, bei Straftat strafrechtliche Verfolgung.</li><li>Umweltaufsichtspersonal, das seine Pflichten vernachlässigt oder seine Befugnisse missbraucht, erhält eine Bestrafung, bei Straftat strafrechtliche Verfolgung.</li></ul><h2 id="vi-offentliche-beteiligung-und-umweltklage-im-offentlichen-interesse" tabindex="-1">VI. Öffentliche Beteiligung und Umweltklage im öffentlichen Interesse <a class="header-anchor" href="#vi-offentliche-beteiligung-und-umweltklage-im-offentlichen-interesse" aria-label="Permalink to &quot;VI. Öffentliche Beteiligung und Umweltklage im öffentlichen Interesse&quot;">​</a></h2><p>Die Öffentlichkeit hat das Recht, am Umweltschutz teilzunehmen, und die spezifischen Wege umfassen:</p><ol><li>Abgabe von Meinungen und Vorschlägen zu Projekten der Umweltverträglichkeitsprüfung.</li><li>Meldung und Beschwerde über Handlungen, die die Umwelt verschmutzen und die Ökologie zerstören.</li><li>Gründung von Umweltschutzorganisationen gemäß Gesetz, Beteiligung an der Umweltaufsicht und gemeinnützigen Aktivitäten.</li><li>Für Handlungen, die die Umwelt verschmutzen, die Ökologie zerstören und das öffentliche Interesse schädigen, können Umweltschutzorganisationen eine Umweltklage im öffentlichen Interesse beim Symbiose-Gericht einreichen.</li></ol><h2 id="schlussfolgerung" tabindex="-1">Schlussfolgerung <a class="header-anchor" href="#schlussfolgerung" aria-label="Permalink to &quot;Schlussfolgerung&quot;">​</a></h2><p>Das 《Gesetz zum Umweltschutz》 ist die rechtliche Gewährleistung des Konzepts der nachhaltigen Entwicklung der Anker-Symbiose-Zivilisation. Durch den Aufbau von Systemen wie Umweltverträglichkeitsprüfung, ökologischer Schutzgrenze und Gesamtmengensteuerung integriert es den Umweltschutz in alle Ausbeutungs- und Kultivierungsaktivitäten, gewährleistet die Nachhaltigkeit des Ursprungs des Universums und des Ökosystems und schützt die ewige Überlebensgrundlage für den gemeinsamen Fortschritt aller Rassen.</p><h2 id="verwandte-dokumente" tabindex="-1">Verwandte Dokumente <a class="header-anchor" href="#verwandte-dokumente" aria-label="Permalink to &quot;Verwandte Dokumente&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Allgemeine Grundsätze der Symbiose-Verfassung)</li><li>39-住房与环境保障 (Wohn- und Umgebungsgarantie)</li><li>15-能量循环与转化法则 (Gesetz des Energiekreislaufs und der Energieumwandlung)</li><li>53-奇特生命识别标准 (Identifikationsstandard für seltsames Leben)</li></ul>',34)])])}const c=n(s,[["render",u]]);export{m as __pageData,c as default};
